#!/usr/bin/env python3
"""AI-authored partial transcription after visually reading the linked captures.

Only quoted spans and their question clues were checked; this does not certify
complete-page OCR or represent an expert/human review. Existing notes/banks are
left unchanged. Capture hashes bind each review to the inspected local image.
"""
import json,hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
SOURCES=json.loads((ROOT/'public/data/source-pages.json').read_text())['pages']
reviews=[];questions=[]
def page(k):return 'seoyangsa-'+('gichul-page-'+k[1:] if k.startswith('g') else 'textbook-page-'+k)
def captures(k):
 out=[]
 for c in SOURCES[page(k)]['captures']:
  raw=(ROOT/'public'/c['src'].lstrip('/')).read_bytes()
  assert hashlib.sha256(raw).hexdigest()==c['sha256']
  out.append({'src':c['src'],'sha256':c['sha256']})
 return out
def review(k,status,summary,reason=None,duplicateOf=None):
 r=dict(page=page(k),status=status,captures=captures(k),summary=summary)
 if reason:r['reason']=reason
 if duplicateOf:r['duplicateOf']=page(duplicateOf)
 reviews.append(r)
def q(k,answer,prompt,quote,location,aliases=None,explain=None,topic=None):
 idx=1+sum(x['page']==page(k) for x in questions)
 cap=captures(k)[0]
 questions.append(dict(id=f'seoyangsa-capture-practice-{k}-{idx}',page=page(k),kind='short',prompt=prompt,answer=answer,acceptedAnswers=aliases or [],evidence=[{'page':page(k),'quote':quote}],captureEvidence=[dict(**cap,quote=quote,location=location)],explain=explain or f'{answer}: {quote}',topic=topic or answer))

